    note(f,d=.12,type='sine',v=.05,slide=0,delay=0,bus=null){if(muted)return;this.resume();if(!this.a)return;const t=this.a.currentTime+delay,o=this.a.createOscillator(),g=this.a.createGain();o.type=type;o.frequency.setValueAtTime(f,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(40,f+slide),t+d);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(v,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g).connect(bus||this.master);o.start(t);o.stop(t+d+.02)}
