    tick(){if(muted||!running||paused||!this.a)return;const s=this.scales[this.world],patterns=[[0,2,1,3,2,1,0,2],[0,1,2,1,3,2,1,0],[0,2,3,2,1,2,0,1],[0,1,2,3,2,1,3,2]],n=patterns[this.world][this.step%8],beat=this.step%4;this.note(s[n],.18,this.world===2?'sine':'triangle',.018,0,0,this.music);if(beat===0)this.note(s[0]/2,.28,'sine',.012,0,0,this.music);if(this.world===2&&this.step%8===4)this.note(s[2]*2,.11,'square',.006,45,0,this.music);this.step++}
