    if(keys.left){p.vx=Math.max(-285,p.vx-accel*dt);p.dir=-1}if(keys.right){p.vx=Math.min(285,p.vx+accel*dt);p.dir=1}if(!keys.left&&!keys.right)p.vx*=Math.pow(onSlick ? .22 : .002,dt);p.vy+=G*dt;p.x=Math.max(0,Math.min(L.width-p.w,p.x+p.vx*dt));const oldBottom=p.y+p.h,impactVy=p.vy;p.y+=p.vy*dt;p.on=false;p.platform=null;
    [...L.platforms,...L.moving].sort((a,b)=>a.y-b.y).some(q=>landOn(p,q,oldBottom));if(p.on&&impactVy>330){audio.land();burst(p.x+35,p.y+54,'#ffffffaa',4,90)}
