  function completeLevel(){if(completing)return;completing=true;running=false;audio.win();burst(game.player.x,game.player.y,'#ffdf4f',32,300);setTimeout(()=>{const next=levelIndex+1;progress.unlocked=Math.max(progress.unlocked,next);localStorage.setItem('jellyUnlocked',progress.unlocked);if(next>=JELLY_LEVELS.length){finishGame();return}const oldWorld=Math.floor(levelIndex/3),newWorld=Math.floor(next/3);levelIndex=next;if(newWorld>oldWorld)showStory(newWorld,()=>newGame(next));else showStory(newWorld,()=>newGame(next),{kicker:'A NEW CLUE!',title:JELLY_LEVELS[next].name,text:'Jelly found another piece of the trail. Her family’s familiar scent is growing stronger!'})},850)}
