  function drawLouisiana(s){ctx.fillStyle=s==='frenchquarter'?'#665276':'#173e49';if(s==='frenchquarter'){for(let i=0;i<16;i++){const x=i*260;ctx.fillRect(x,H-320,215,180);ctx.strokeStyle='#d4c0a5';ctx.lineWidth=5;ctx.strokeRect(x+15,H-280,185,42);for(let k=0;k<4;k++){ctx.beginPath();ctx.moveTo(x+25+k*48,H-280);ctx.lineTo(x+25+k*48,H-238);ctx.stroke()}}}else{for(let i=0;i<25;i++){const x=i*160;ctx.fillRect(x,H-300,15,170);ctx.beginPath();ctx.arc(x,H-300,74,0,7);ctx.fill();ctx.strokeStyle='#6e8d64';ctx.lineWidth=3;for(let k=0;k<6;k++){ctx.beginPath();ctx.moveTo(x-55+k*20,H-290);ctx.quadraticCurveTo(x-40+k*20,H-230,x-50+k*20,H-180);ctx.stroke()}}ctx.fillStyle='#294f5b';ctx.fillRect(0,H-140,game.width,140)}if(s==='riverboat'){ctx.fillStyle='#f3e2c3';roundRect(620,H-250,440,110,12);ctx.fill();ctx.fillStyle='#d54b58';ctx.fillRect(650,H-280,370,32);ctx.beginPath();ctx.arc(650,H-140,70,0,7);ctx.strokeStyle='#d54b58';ctx.lineWidth=12;ctx.stroke()}ctx.fillStyle='#ffde5e';for(let i=0;i<45;i++){ctx.globalAlpha=.35+.5*Math.sin(game.time*3+i);ctx.beginPath();ctx.arc(i*97,H-300+(i%7)*23,3,0,7);ctx.fill()}ctx.globalAlpha=1}
