  function drawPlatforms(){const w=worlds[Math.floor(levelIndex/3)];ctx.save();ctx.translate(-game.camera,0);game.platforms.forEach(p=>drawGround(p,w));game.moving.forEach(m=>drawMoving(m,w));const g=game.goal;ctx.fillStyle='#fffdf2';roundRect(g.x,g.y,g.w,g.h,18);ctx.fill();ctx.strokeStyle=w.accent;ctx.lineWidth=6;ctx.stroke();ctx.font='43px serif';ctx.textAlign='center';ctx.fillText(levelIndex===11?'🏠':'💌',g.x+46,g.y+62);ctx.font='800 12px Nunito';ctx.fillStyle=w.accent;ctx.fillText(levelIndex===11?'HOME':'CLUE',g.x+46,g.y+90);ctx.restore()}
  function drawGround(p,w){ctx.fillStyle=w.ground;roundRect(p.x,p.y,p.w,p.h,16);ctx.fill();ctx.fillStyle=w.top;roundRect(p.x,p.y,p.w,18,11);ctx.fill();ctx.fillStyle='#ffffff18';for(let x=p.x+20;x<p.x+p.w-15;x+=48)ctx.fillRect(x,p.y+37,23,4);ctx.fillStyle='#0000000c';for(let x=p.x+10;x<p.x+p.w;x+=65){ctx.beginPath();ctx.arc(x,p.y+70,12,0,7);ctx.fill()}}
  function drawMoving(m,w){ctx.save();ctx.translate(m.x,m.y);ctx.fillStyle=m.kind===0?w.accent:m.kind===1?'#ffd34f':'#fff9dc';roundRect(0,0,m.w,m.h,10);ctx.fill();ctx.strokeStyle='#ffffffb5';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#173157';ctx.textAlign='center';ctx.font='800 11px Nunito';const labels={midtown:'TAXI',centralpark:'LEAF',brooklyn:'BRIDGE',venice:'BOARD',studio:'TAKE!',pier:'SURF',frenchquarter:'JAZZ',bayou:'LOG',riverboat:'DECK',grove:'ORANGE',eola:'SWAN',home:'LOVE'};ctx.fillText(labels[game.scene],m.w/2,17);ctx.restore()}
  function drawCollectibles(){ctx.save();ctx.translate(-game.camera,0);game.treats.forEach(t=>{if(t.taken)return;const y=t.y+Math.sin(game.time*3+t.spin)*5;ctx.save();ctx.translate(t.x,y);ctx.rotate(Math.sin(t.spin)*.12);ctx.fillStyle='#ed9f39';roundRect(-18,-10,36,20,9);ctx.fill();ctx.fillStyle='#ffd782';ctx.beginPath();ctx.arc(-16,-6,8,0,7);ctx.arc(16,6,8,0,7);ctx.fill();ctx.strokeStyle='#fff5ca';ctx.lineWidth=2;ctx.stroke();ctx.restore()});ctx.restore()}
  function drawEnemies(){ctx.save();ctx.translate(-game.camera,0);const row=Math.floor(levelIndex/3),cw=384,ch=256;game.enemies.forEach(e=>{const frame=e.stun?3:e.frame,bob=e.state==='move'?Math.sin(game.time*7+e.phase)*2:0,warn=e.state==='warn',attack=e.state==='attack',stunned=e.stun>0,stretchX=attack ? 1.13 : (warn ? .91 : 1),stretchY=attack ? .9 : (warn ? 1.09 : 1),rot=stunned?Math.sin(game.time*17)*.11:attack?e.dir*.055:0;ctx.save();ctx.globalAlpha=.18;ctx.fillStyle='#172239';ctx.beginPath();ctx.ellipse(e.x+34,e.homeY+56,30*(attack?1.35:1),7,0,0,7);ctx.fill();ctx.restore();if(attack){ctx.save();ctx.globalAlpha=.15;ctx.translate(e.lastX+(e.dir<0?68:0),e.lastY-8);if(e.dir<0)ctx.scale(-1,1);ctx.drawImage(enemySheet,frame*cw,row*ch,cw,ch,0,0,68,60);ctx.restore()}ctx.save();ctx.translate(e.x+34,e.y+22+bob);ctx.rotate(rot);ctx.scale((e.dir<0?-1:1)*stretchX,stretchY);ctx.translate(-34,-30);if(warn){ctx.globalAlpha=.35+.25*Math.sin(game.time*22);ctx.fillStyle='#ffdf4c';ctx.beginPath();ctx.arc(34,28,43,0,7);ctx.fill();ctx.globalAlpha=1}ctx.drawImage(enemySheet,frame*cw,row*ch,cw,ch,0,0,68,60);ctx.restore();if(warn){ctx.save();ctx.translate(e.x+34,e.y-20);ctx.scale(1+Math.sin(game.time*19)*.08,1+Math.sin(game.time*19)*.08);ctx.fillStyle='#fff';ctx.strokeStyle='#173157';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,14,0,7);ctx.fill();ctx.stroke();ctx.fillStyle='#ef4b55';ctx.font='900 18px Nunito';ctx.textAlign='center';ctx.fillText('!',0,6);ctx.restore()}if(stunned){for(let i=0;i<3;i++){const a=game.time*4+i*2.1;ctx.font='15px sans-serif';ctx.textAlign='center';ctx.fillText('⭐',e.x+34+Math.cos(a)*24,e.y-12+Math.sin(a)*8)}}if(attack&&row===1){ctx.fillStyle='#66e1f2';for(let i=0;i<3;i++){ctx.beginPath();ctx.arc(e.x+34-e.dir*(18+i*9),e.y+52+i%2*4,3,0,7);ctx.fill()}}if(e.state==='attack'&&row===2){ctx.fillStyle='#ffe45d';ctx.font='16px sans-serif';ctx.fillText('♪',e.x+55,e.y-3)}});game.waves.forEach(w=>{ctx.fillStyle='#ffd34f';ctx.font='25px sans-serif';ctx.textAlign='center';ctx.fillText(w.vx>0?'♪':'♫',w.x,w.y)});ctx.restore()}
  function drawPlayer(){const p=game.player,cell=362,frame=p.barkCd>.47?6:!p.on?(p.vy<0?3:4):Math.abs(p.vx)>30?(1+Math.floor(p.anim*9)%2):0,sx=(frame%4)*cell,sy=Math.floor(frame/4)*cell,air=!p.on,stretchY=air?(p.vy<0?1.08:.96):1,stretchX=air?(p.vy<0?.94:1.04):1;ctx.save();ctx.globalAlpha=.17;ctx.fillStyle='#173157';ctx.beginPath();ctx.ellipse(p.x-game.camera+36,p.y+57,air?20:31,6,0,0,7);ctx.fill();ctx.restore();ctx.save();ctx.translate(p.x-game.camera+(p.dir<0?p.w:0)+p.w/2,p.y+18);ctx.scale((p.dir<0?-1:1)*stretchX,stretchY);ctx.translate(-p.w/2,-36);if(p.inv&&Math.floor(p.inv*10)%2)ctx.globalAlpha=.32;ctx.drawImage(jelly,sx,sy,cell,cell,0,0,p.w,72);ctx.restore()}
  function drawFX(){ctx.save();ctx.translate(-game.camera,0);game.speedLines.forEach(o=>{ctx.globalAlpha=Math.max(0,o.life*3);ctx.strokeStyle=o.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(o.x,o.y);ctx.lineTo(o.x-o.vx*.12,o.y);ctx.stroke()});game.barks.forEach(b=>{ctx.strokeStyle=`rgba(255,72,145,${b.life*2})`;ctx.lineWidth=7;ctx.beginPath();ctx.arc(b.x,b.y,b.r,0,7);ctx.stroke();ctx.font=`${18+b.r*.17}px sans-serif`;ctx.fillStyle='#ef4b8f';ctx.fillText('♥',b.x+b.dir*b.r,b.y)});game.particles.forEach(o=>{ctx.globalAlpha=Math.max(0,o.life);ctx.fillStyle=o.color;ctx.beginPath();ctx.arc(o.x,o.y,o.size,0,7);ctx.fill()});ctx.restore()}
  function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
  function loop(t){const dt=Math.min(.032,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
  function startFresh(){levelIndex=0;showStory(0,()=>newGame(0))}$('#playBtn').onclick=startFresh;$('#continueBtn').onclick=()=>{levelIndex=Math.min(progress.unlocked,11);showStory(Math.floor(levelIndex/3),()=>newGame(levelIndex))};if(progress.unlocked>0)$('#continueBtn').hidden=false;$('#storyBtn').onclick=()=>storyNext?.();$('#pauseBtn').onclick=()=>setPause(true);$('#resumeBtn').onclick=()=>setPause(false);$('#restartBtn').onclick=()=>newGame(levelIndex);$('#mapBtn').onclick=showMap;$('#closeMap').onclick=()=>{ui.map.hidden=true;ui.pause.hidden=false};$('#replayBtn').onclick=startFresh;
  function setPause(v){paused=v;ui.pause.hidden=!v;if(!v){audio.resume();canvas.focus()}}function showMap(){ui.pause.hidden=true;ui.map.hidden=false;renderMap()}function renderMap(){const cards=$('#worldCards');cards.innerHTML='';worlds.forEach((w,i)=>{const b=document.createElement('button');b.className='world-card';b.style.background=`linear-gradient(145deg,${w.sky[0]},${w.accent})`;b.disabled=progress.unlocked<i*3;b.innerHTML=`<span class="icon">${w.icon}</span><strong>${w.city}</strong><small>${b.disabled?'Keep exploring to unlock':i===Math.floor(levelIndex/3)?'You are here':'Play this chapter'}</small>`;b.onclick=()=>{levelIndex=i*3;showStory(i,()=>newGame(levelIndex))};cards.appendChild(b)})}
  addEventListener('keydown',e=>{if(['ArrowLeft','a','A'].includes(e.key))keys.left=true;if(['ArrowRight','d','D'].includes(e.key))keys.right=true;if([' ','ArrowUp','w','W'].includes(e.key)){e.preventDefault();jump()}if(['x','X'].includes(e.key))bark();if(e.key==='Escape'&&running)setPause(!paused)});addEventListener('keyup',e=>{if(['ArrowLeft','a','A'].includes(e.key))keys.left=false;if(['ArrowRight','d','D'].includes(e.key))keys.right=false});document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key,down=e=>{e.preventDefault();if(k==='jump')jump();else if(k==='bark')bark();else keys[k]=true},up=e=>{e.preventDefault();if(k==='left'||k==='right')keys[k]=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
  const soundBtn=$('#soundBtn');soundBtn.textContent=muted?'🔇':'🔊';soundBtn.setAttribute('aria-label',muted?'Unmute sound':'Mute sound');soundBtn.onclick=()=>{muted=!muted;localStorage.setItem('jellyMuted',muted?'1':'0');soundBtn.textContent=muted?'🔇':'🔊';soundBtn.setAttribute('aria-label',muted?'Unmute sound':'Mute sound');if(!muted)audio.resume()};addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').hidden=false});$('#installBtn').onclick=async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').hidden=true}};if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
